import React, { useState } from "react";
import { Form, FormGroup, Label, Input, Row, Col } from "reactstrap";
import "../Styles/CompanyRegister.css"; // <-- نفس الاسم اللي عندك

const StudentRegister = () => {
  const [fullName, setFullName] = useState("");
  const [studentId, setStudentId] = useState("");
  const [email, setEmail] = useState("");
  const [major, setMajor] = useState("");
  const [password, setPassword] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    const payload = { fullName, studentId, email, major, password };
    console.log("Student payload:", payload);
    alert("Student Registered ✅ (mock)");
  };

  return (
    <div className="reg-page">
      <h1 className="reg-title">
        Create your <span className="accent">account</span>
      </h1>
      <p className="reg-sub">Please fill in your details to continue:</p>

      <div className="reg-card">
        <Form onSubmit={handleSubmit}>
          <FormGroup>
            <Label>Full Name</Label>
            <Input
              type="text"
              placeholder="Your name"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              required
            />
          </FormGroup>

          <FormGroup>
            <Label>Student ID</Label>
            <Input
              type="text"
              placeholder="202XXXXX"
              value={studentId}
              onChange={(e) => setStudentId(e.target.value)}
              required
            />
          </FormGroup>

          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Email</Label>
                <Input
                  type="email"
                  placeholder="you@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
            <Col md={6}>
              <FormGroup>
                <Label>Major</Label>
                <Input
                  type="text"
                  placeholder="Software Engineering"
                  value={major}
                  onChange={(e) => setMajor(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
          </Row>

          <FormGroup>
            <Label>Password</Label>
            <Input
              type="password"
              placeholder="********"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </FormGroup>

          <button className="reg-btn">Sign up</button>
          <p className="login-text">
            Already have an account? <span>Log in now!</span>
          </p>
        </Form>
      </div>
    </div>
  );
};

export default StudentRegister;
